S={'phase':'init','d':0.0,'fd':0.0,'pa':0.0,'aimb':None,'n':0,'woke':False,'pulls':0}

def wrap(a):
    while a>180: a-=360
    while a<-180: a+=360
    return a

def cl(x,a,b):
    return max(a,min(b,x))

def topts(v,lst):
    o=v.get('origin',[0,0]); out=[]
    for p in lst or []:
        try:
            b=math.radians(p[0]); d=p[1]
            out.append((o[0]+d*math.cos(b),o[1]+d*math.sin(b)))
        except Exception:
            pass
    return out

def ray(P,ang,walls,hw=1.1):
    c=math.cos(math.radians(ang)); s=math.sin(math.radians(ang))
    free=9.0
    for w in walls:
        dx=w[0]-P[0]; dy=w[1]-P[1]
        al=dx*c+dy*s; la=-dx*s+dy*c
        if al>0 and abs(la)<hw and al<free: free=al
    clear=3.0
    for w in walls:
        dx=w[0]-P[0]; dy=w[1]-P[1]
        al=dx*c+dy*s; la=-dx*s+dy*c
        if 0<al<min(free,5.0):
            clear=min(clear,abs(la))
    return free,clear

def control(obs):
    S['n']+=1
    dt=obs.get('dt',0.1) or 0.1
    rig=obs['rig']; P=rig['trailer_rear']; th=rig['trailer_heading_deg']
    back=wrap(th+180.0)
    hitch=obs['hitch_deg']
    vnow=obs['motion']['v_mps']
    look=-23
    views=obs.get('views') or {}
    walls=[];corners=[]
    for name,v in views.items():
        if not isinstance(v,dict): continue
        walls+=topts(v,v.get('walls'))
        for c in topts(v,v.get('target_corners')):
            if all(math.hypot(c[0]-q[0],c[1]-q[1])>0.6 for q in corners):
                corners.append(c)
    vf=rig.get('vehicle_front',3.55); vhw=rig.get('vehicle_half_width',0.925)
    rc=False; lc=False
    for w in walls:
        if 0.8<w[0]<vf+0.4:
            if w[1]<0 and -w[1]-vhw<0.3: rc=True
            if w[1]>0 and w[1]-vhw<0.3: lc=True
    if S['phase']=='init':
        if vnow<0: S['d']+=-vnow*dt
        if S['d']>1.5: S['phase']='rev'
        else:
            st=cl(2.0*hitch,-12,12)
            if rc: st=min(st,0.0)
            if lc: st=max(st,0.0)
            return (st,-0.8,look)
    if S['phase']=='fwd':
        if vnow>0: S['fd']+=vnow*dt
        if (abs(hitch)<5 and S['fd']>1.5) or S['fd']>4.0:
            S['phase']='rev'
        else:
            st=0.0
            if rc: st=10.0
            if lc: st=-10.0
            return (st,1.0,look)
    if abs(hitch)>40:
        S['phase']='fwd'; S['fd']=0.0; S['pulls']+=1
        return (0.0,1.0,look)
    bayd=99; f0=5.0
    if not views:
        aimb=S['aimb'] if S['aimb'] is not None else back
    else:
        aimb=None
        f0,_=ray(P,back,walls,0.95)
        if len(corners)>=4:
            cx=sum(c[0] for c in corners)/len(corners); cy=sum(c[1] for c in corners)/len(corners)
            sxx=sum((c[0]-cx)**2 for c in corners); syy=sum((c[1]-cy)**2 for c in corners); sxy=sum((c[0]-cx)*(c[1]-cy) for c in corners)
            ang=0.5*math.atan2(2*sxy,sxx-syy)
            u=(math.cos(ang),math.sin(ang))
            if u[0]*(cx-P[0])+u[1]*(cy-P[1])<0: u=(-u[0],-u[1])
            s=(P[0]-cx)*u[0]+(P[1]-cy)*u[1]
            la=min(s+3.0,1.5)
            q=(cx+u[0]*la,cy+u[1]*la)
            aimb=math.degrees(math.atan2(q[1]-P[1],q[0]-P[0]))
            bayd=math.hypot(cx-P[0],cy-P[1])
        else:
            tg=obs.get('target') or {}
            if tg.get('in_sight') and tg.get('dist_m') is not None:
                e0=rig['eye']; b=math.radians(tg['bearing_deg']); d=tg['dist_m']
                tx=e0[0]+d*math.cos(b); ty=e0[1]+d*math.sin(b)
                tb=math.degrees(math.atan2(ty-P[1],tx-P[0])); td=math.hypot(tx-P[0],ty-P[1])
                fr,_=ray(P,tb,walls,1.0)
                if fr>=min(td-0.3,8.5) and abs(wrap(tb-back))<70:
                    aimb=tb; bayd=td
        if aimb is None:
            best=None
            for k in range(-14,15):
                a=k*5.0
                fr,clr=ray(P,back+a,walls)
                sc=min(fr,9.0)+2.0*min(clr,1.8)-0.03*abs(a)-0.02*abs(a-S['pa'])
                if best is None or sc>best[0]: best=(sc,a)
            a=0.6*S['pa']+0.4*best[1]
            S['pa']=a
            aimb=back+a
        S['aimb']=aimb
    e=wrap(aimb-back)
    hd=cl(-0.8*e,-30,30)
    steer=cl(0.75*hd+2.0*(hitch-hd),-34,34)
    if rc: steer=min(steer,0.0)
    if lc: steer=max(steer,0.0)
    v=-1.0
    if f0<2.0 or bayd<5: v=-0.5
    if bayd<2.5: v=-0.35
    if views and f0<0.35:
        if bayd<3.5:
            v=0.0
            if not S['woke']:
                S['woke']=True; wake('stopped near bay, bayd=%.1f e=%.0f h=%.0f'%(bayd,e,hitch))
        else:
            S['phase']='fwd'; S['fd']=0.0; S['pulls']+=1
            if S['pulls']>=3 and not S['woke']:
                S['woke']=True; wake('pulled forward %d times'%S['pulls'])
            return (0.0,1.0,look)
    if S['n']%20==0:
        print('t%.0f h%.0f hd%.0f e%.0f st%.0f f%.1f bay%.1f c%d rc%d lc%d'%(obs['t'],hitch,hd,e,steer,f0,bayd,len(corners),rc,lc))
    return (steer,v,look)

