import math
S={'phase':'fwd','fd':0.0,'fgoal':3.0,'psi':0.0,'n':0,'woke':0,'pulls':0,'D':-76.0,'first':True,'e':0.0}
L=2.75
def wrap(a):
    while a>180: a-=360
    while a<-180: a+=360
    return a
def cl(x,a,b):
    return max(a,min(b,x))
def topts(v,lst):
    o=v.get('origin',[0,0]); out=[]
    for p in lst or []:
        try:
            b=math.radians(p[0]); d=p[1]
            out.append((o[0]+d*math.cos(b),o[1]+d*math.sin(b)))
        except Exception:
            pass
    return out
def ray(P,ang,walls,hw=1.0):
    c=math.cos(math.radians(ang)); s=math.sin(math.radians(ang))
    free=9.0
    for w in walls:
        dx=w[0]-P[0]; dy=w[1]-P[1]
        al=dx*c+dy*s; la=-dx*s+dy*c
        if al>0 and abs(la)<hw and al<free: free=al
    return free
def wk(m):
    if S['woke']<3:
        S['woke']+=1; wake(m)
def control(obs):
    S['n']+=1
    dt=obs.get('dt',0.1) or 0.1
    v=obs['motion']['v_mps']; st=obs['steer_deg']
    S['psi']+=math.degrees(v*math.tan(math.radians(st))/L*dt)
    hitch=obs['hitch_deg']; rig=obs['rig']; P=rig['trailer_rear']
    back=wrap(rig['trailer_heading_deg']+180.0)
    tbw=wrap(S['psi']+back)
    look=-23
    views=obs.get('views') or {}
    walls=[];corners=[]
    for name,vv in views.items():
        if not isinstance(vv,dict): continue
        walls+=topts(vv,vv.get('walls'))
        for c in topts(vv,vv.get('target_corners')):
            if all(math.hypot(c[0]-q[0],c[1]-q[1])>0.6 for q in corners):
                corners.append(c)
    hw=rig.get('trailer_half_width',0.85); vf=rig.get('vehicle_front',3.55); vhw=rig.get('vehicle_half_width',0.925)
    cb=math.cos(math.radians(back)); sb=math.sin(math.radians(back))
    tdang=False; fdang=False
    for w in walls:
        dx=w[0]-P[0]; dy=w[1]-P[1]
        al=dx*cb+dy*sb; la=-dx*sb+dy*cb
        if 0<al<0.4 and abs(la)<hw+0.15: tdang=True
        if -1.2<al<=0 and abs(la)<hw+0.15: tdang=True
        if 1.0<w[0]<vf+0.3 and abs(w[1])-vhw<0.25: fdang=True
    if S['phase']=='fwd':
        if v>0: S['fd']+=v*dt
        if S['fd']>=S['fgoal'] and (abs(hitch)<15 or S['fd']>4.5):
            S['phase']='rev'; S['first']=False
        else:
            stf=12.0 if S['first'] else 0.0
            if fdang:
                wk('front close to rail while pulling forward'); return (stf,0.0,look)
            return (stf,1.0,look)
    if abs(hitch)>50:
        S['phase']='fwd'; S['fd']=0.0; S['fgoal']=2.0; S['pulls']+=1
        if S['pulls']>=2: wk('hitch over 50, pulled forward %d times'%S['pulls'])
        return (0.0,1.0,look)
    bayd=99.0; src='D'
    if not views:
        e=S['e']
    else:
        e=None
        if len(corners)>=3:
            cx=sum(c[0] for c in corners)/len(corners); cy=sum(c[1] for c in corners)/len(corners)
            sxx=sum((c[0]-cx)**2 for c in corners); syy=sum((c[1]-cy)**2 for c in corners); sxy=sum((c[0]-cx)*(c[1]-cy) for c in corners)
            ang=0.5*math.atan2(2*sxy,sxx-syy)
            u=(math.cos(ang),math.sin(ang))
            if u[0]*(cx-P[0])+u[1]*(cy-P[1])<0: u=(-u[0],-u[1])
            s=(P[0]-cx)*u[0]+(P[1]-cy)*u[1]
            la=min(s+3.0,1.5)
            q=(cx+u[0]*la,cy+u[1]*la)
            aimb=math.degrees(math.atan2(q[1]-P[1],q[0]-P[0]))
            bayd=math.hypot(cx-P[0],cy-P[1])
            e=wrap(aimb-back); src='bay'
        if e is None:
            tg=obs.get('target') or {}
            if tg.get('in_sight') and tg.get('dist_m') is not None:
                e0=rig['eye']; b=math.radians(tg['bearing_deg']); d=tg['dist_m']
                tx=e0[0]+d*math.cos(b); ty=e0[1]+d*math.sin(b)
                tb=math.degrees(math.atan2(ty-P[1],tx-P[0])); td=math.hypot(tx-P[0],ty-P[1])
                if ray(P,tb,walls,1.0)>=min(td-0.3,8.5) and abs(wrap(tb-back))<100:
                    e=wrap(tb-back); bayd=td; src='tgt'
        if e is None:
            e=wrap(S['D']-tbw)
        S['e']=e
    e=cl(e,-60,60)
    hd=cl(-0.9*e,-40,40)
    steer=cl(0.7*hd+2.0*(hitch-hd),-34,34)
    sp=-0.7
    if bayd<5: sp=-0.5
    if bayd<2.5: sp=-0.35
    if tdang:
        sp=0.0; wk('trailer close to rail: e=%.0f h=%.0f bayd=%.1f src=%s'%(e,hitch,bayd,src))
    if fdang:
        sp=0.0; wk('vehicle front close to rail: e=%.0f h=%.0f src=%s'%(e,hitch,src))
    if S['n']%15==0:
        print('t%.0f h%.0f hd%.0f e%.0f st%.0f tbw%.0f bay%.1f %s c%d'%(obs['t'],hitch,hd,e,steer,tbw,bayd,src,len(corners)))
    return (steer,sp,look)

