    if obs.get('status') in ('PINNED','JACKKNIFED') or (mind<0.3 and v<-0.05) or abs(phi)>75:
        backs+=1;mode='fwd';trav=0.0;fwdD=2.0;fsteer=cl(-0.6*phi,-35,35)
