        if backs==3: wake('several backoffs, check')
        return (fsteer,0.9,0)
    if gz==-41 and gt>1.5: gz=53;gt=0.0
    elif gz==53 and gt>0.9: gz=-41;gt=0.0
    rwx,rwy=tow(r[0],r[1])
