            try:
                b=math.radians(w[0]);px=o[0]+w[1]*math.cos(b);py=o[1]+w[1]*math.sin(b)
                kk.append((X+px*c-py*s,Y+px*s+py*c))
            except Exception: pass
    if len(kk)>=2:
