        d2=rdist(px,py,tcx,tcy,tha,6.75,1.275)
        if d1<0.03 or d2<0.03: continue
        LP.append((px,py))
        if px>vf-2.5:
            if py>0: fl=min(fl,d1)
            else: fr=min(fr,d1)
        else:
            if py>0: rl=min(rl,d1)
            else: rr=min(rr,d1)
        mr=min(mr,d2)
    gt+=dt
    if gt>GZ[gi][1]: gi=(gi+1)%2;gt=0.0
    look=GZ[gi][0]
    status=obs.get('status')
    if phase=='A':
        if mo.get('hold_s',0)>0: return (30.0,0.0,look)
        trav+=max(v,0)*dt
        if trav<4.0 and fl>0.3 and fr>0.3:
            if n%15==0: print('FWD t=%.1f phi=%.1f trav=%.1f fl=%.2f fr=%.2f H=%.0f'%(obs['t'],phi,trav,fl,fr,math.degrees(H)))
            return (30.0,0.7,look)
        phase='B';print('to B t=%.1f phi=%.1f H=%.0f'%(obs['t'],phi,math.degrees(H)))
