            if cc>0: lefts.append((al,cc))
            else: rights.append((al,cc))
            if al<5:
                if cc>0: cp=min(cp,cc)
                else: cn=min(cn,-cc)
        if al>0 and abs(cc)<1.35: free=min(free,al)
