        angs=[a for a in (sl,sr) if a is not None]
        ang=sum(angs)/len(angs) if angs else 0.0
        if cp<99 and cn<99: ee=(cp-cn)/2
        elif cp<99: ee=min(cp-2.0,0)
        elif cn<99: ee=max(2.0-cn,0)
        else: ee=0.0
        a=cl(ang,-30,30)+cl(6*ee,-15,15)
        if KW is not None and T-KW[2]<3:
            dx=KW[0]-X;dy=KW[1]-Y;kx=dx*c+dy*s;ky=-dx*s+dy*c
            ak=nrm(math.degrees(math.atan2(ky-r[1],kx-r[0]))-math.degrees(beta))
            kd=math.hypot(kx-r[0],ky-r[1])
            if abs(ak)<60 and kd>4: a=cl(ak,-25,25)+cl(3*ee,-6,6);usedK=True
            elif kd<=4: a=cl(ang,-10,10);usedK=True
        a=cl(a,-30,30)
        if af is None: af=a
        af+=0.3*(a-af)
        phid=cl(-1.5*af,-35,35)
    if free<0.8 and not usedK: return stop(obs,'wall behind trailer free=%.2f phase %s'%(free,phase),look)
    vv=min(v,-0.3)
    p=math.radians(phi)
    pdd=-1.0*abs(vv)*math.radians(phi-phid)
    om=(pdd+vv*math.sin(p)/L2)/(1-C*math.cos(p)/L2)
    steer=cl(math.degrees(math.atan(om*L/vv)),-42,42)
    if rl<0.45 and steer>-8: steer=-8
    if rr<0.45 and steer<8: steer=8
    if fl<0.4 and steer<-8: steer=-8
    if fr<0.4 and steer>8: steer=8
    mn=min(mt,mr)
    spd=-0.45 if (mn<0.8 or abs(phi)>25 or phase=='B') else (-0.8 if mn<1.5 else -1.2)
    if abs(st-steer)>25: spd=max(spd,-0.25)
    if n%15==0:
        print('%s t=%.1f phi=%.1f phid=%.0f psi=%.0f st=%.0f fl=%.2f rl=%.2f fr=%.2f rr=%.2f mr=%.2f free=%.1f K=%s'%(phase,obs['t'],phi,phid,psi_t,steer,fl,rl,fr,rr,mr,free,usedK))
    return (steer,spd,look)

