    if n%15==0:
        print('%s t=%.1f phi=%.1f phid=%.0f ang=%s st=%.0f fl=%.2f rl=%.2f fr=%.2f rr=%.2f mr=%.2f free=%.1f'%(phase,obs['t'],phi,phid,None if ang is None else round(ang),steer,fl,rl,fr,rr,mr,free))
    return (steer,spd,look)

