import math
L=3.9;L2=10.2;C=0.35
X=0.0;Y=0.0;H=0.0;T=0.0
M=[]
n=0;gi=0;gt=0.0;woke=False;af=None
mode='rev';trav=0.0;fsteer=0.0;nf=0;cs=0.0;cclr=9.0
GZ=[(-41,1.0),(53,0.8),(-41,1.0),(-72,0.6)]
def cl(x,a,b): return max(a,min(b,x))
def nrm(a):
    while a>180:a-=360
    while a<-180:a+=360
    return a
def rdist(px,py,cx,cy,ang,hl,hw):
    dx=px-cx;dy=py-cy;ca=math.cos(ang);sa=math.sin(ang)
    lx=dx*ca+dy*sa;ly=-dx*sa+dy*ca
    return math.hypot(max(abs(lx)-hl,0),max(abs(ly)-hw,0))
def fit(pts):
    if len(pts)<3: return None
    xs=[p[0] for p in pts];ys=[p[1] for p in pts]
    if max(xs)-min(xs)<2.0: return None
    mx=sum(xs)/len(xs);my=sum(ys)/len(ys)
    sxx=sum((x-mx)**2 for x in xs);sxy=sum((x-mx)*(y-my) for x,y in zip(xs,ys))
    return math.degrees(math.atan(sxy/sxx))
def sim(s0,stt,sgn,dist,pts,th0,vf,spd):
    x=y=h=0.0;ht=math.radians(th0);s=s0;clr=99.0
    ds=0.1;N=int(dist/ds);rs=20.0*ds/max(spd,0.2)
    for i in range(N):
        s+=cl(stt-s,-rs,rs)
        d=sgn*ds
        hx=x+C*math.cos(h);hy=y+C*math.sin(h)
        x+=d*math.cos(h);y+=d*math.sin(h);h+=d*math.tan(math.radians(s))/L
        nhx=x+C*math.cos(h);nhy=y+C*math.sin(h)
        ht+=((nhx-hx)*(-math.sin(ht))+(nhy-hy)*math.cos(ht))/L2
        if i%3==0 or i==N-1:
            tcx=x+(vf-3.1)*math.cos(h);tcy=y+(vf-3.1)*math.sin(h)
            rcx=nhx-5.35*math.cos(ht);rcy=nhy-5.35*math.sin(ht)
            for px,py in pts:
                d1=rdist(px,py,tcx,tcy,h,3.1,1.275)
                if d1<clr: clr=d1
                d2=rdist(px,py,rcx,rcy,ht,6.75,1.275)
                if d2<clr: clr=d2
    return clr,nrm(math.degrees(h-ht))
def stop(obs,msg,look):
    global woke
    if not woke:
        woke=True;print('STOP '+msg);wake(msg)
    return (obs.get('steer_deg') or 0.0,0.0,look)
def control(obs):
    global X,Y,H,T,M,n,gi,gt,woke,af,mode,trav,fsteer,nf,cs,cclr
    n+=1;dt=obs.get('dt') or 0.1;T+=dt
    mo=obs['motion'];v=mo['v_mps'];st=obs.get('steer_deg') or 0.0
    X+=v*math.cos(H)*dt;Y+=v*math.sin(H)*dt;H+=v*math.tan(math.radians(st))/L*dt
    c=math.cos(H);s=math.sin(H)
    phi=obs['hitch_deg'];rig=obs['rig'];r=rig['trailer_rear'];th=rig['trailer_heading_deg']
    views=obs.get('views') or {}
    for k,vw in views.items():
        if not vw: continue
        o=vw.get('origin',[0,0])
        for w in (vw.get('walls') or []):
            try:
                if w[1]>16: continue
                b=math.radians(w[0]);px=o[0]+w[1]*math.cos(b);py=o[1]+w[1]*math.sin(b)
                M.append((X+px*c-py*s,Y+px*s+py*c,T))
            except Exception: pass
    M=[p for p in M if T-p[2]<7.0]
    vf=rig.get('vehicle_front',5.0)
    if isinstance(vf,(list,tuple)): vf=vf[0]
    try: vf=float(vf)
    except Exception: vf=5.0
    tha=math.radians(th)
    tcx=r[0]+6.75*math.cos(tha);tcy=r[1]+6.75*math.sin(tha)
    LP=[];G={};mn=99
    for p in M:
        dx=p[0]-X;dy=p[1]-Y
        px=dx*c+dy*s;py=-dx*s+dy*c
        d1=rdist(px,py,vf-3.1,0.0,0.0,3.1,1.275)
        d2=rdist(px,py,tcx,tcy,tha,6.75,1.275)
        if d1<0.03 or d2<0.03: continue
        LP.append((px,py));mn=min(mn,d1,d2)
        if min(d1,d2)<4.0: G[(round(px*5),round(py*5))]=(px,py)
    PP=list(G.values())
    gt+=dt
    if gt>GZ[gi][1]: gi=(gi+1)%4;gt=0.0
    look=GZ[gi][0]
    status=obs.get('status')
    if status in ('PINNED','JACKKNIFED'): return stop(obs,'status '+str(status),look)
    if mode=='fwd':
        if mo.get('hold_s',0)>0 and trav<0.05: return (fsteer,0.0,look)
        trav+=max(v,0)*dt
        if n%3==0:
            best=None
            for cand in range(-36,37,6):
                clr,pe=sim(st,cand,1,1.5,PP,th,vf,0.5)
                sc=10*min(clr,0.9)-0.03*abs(pe)
                if best is None or sc>best[0]: best=(sc,cand,clr)
            fsteer=best[1];cclr=best[2]
        if cclr<0.1 and trav>0.2: return stop(obs,'fwd blocked clr=%.2f'%cclr,look)
        if trav<3.0:
            if n%10==0: print('FWD t=%.1f phi=%.1f trav=%.1f fs=%.0f clr=%.2f'%(obs['t'],phi,trav,fsteer,cclr))
            return (fsteer,0.6,look)
        mode='rev';af=None
    if abs(phi)>60: return stop(obs,'hitch %.1f'%phi,look)
    beta=math.radians(th+180.0);ux=math.cos(beta);uy=math.sin(beta)
    lefts=[];rights=[];cp=99;cn=99
    for px,py in LP:
        dx=px-r[0];dy=py-r[1]
        al=dx*ux+dy*uy;cc=ux*dy-uy*dx
        if -1<al<12 and abs(cc)<7:
            if cc>0: lefts.append((al,cc))
            else: rights.append((al,cc))
            if al<5:
                if cc>0: cp=min(cp,cc)
                else: cn=min(cn,-cc)
    sl=fit([p for p in lefts if p[0]>0]);sr=fit([p for p in rights if p[0]>0])
    angs=[a for a in (sl,sr) if a is not None]
    ang=sum(angs)/len(angs) if angs else 0.0
    if cp<99 and cn<99: ee=(cp-cn)/2
    elif cp<99: ee=min(cp-2.0,0)
    elif cn<99: ee=max(2.0-cn,0)
    else: ee=0.0
    a=cl(cl(ang,-25,25)+cl(6*ee,-15,15),-30,30)
    if af is None: af=a
    af+=0.3*(a-af)
    phid=cl(-1.5*af-8,-45,45)
    vv=min(v,-0.3)
    p=math.radians(phi)
    pdd=-0.8*abs(vv)*math.radians(phi-phid)
    om=(pdd+vv*math.sin(p)/L2)/(1-C*math.cos(p)/L2)
    track=cl(math.degrees(math.atan(om*L/vv)),-42,42)
    if n%3==0 or n<3:
        best=None
        for cand in range(-42,43,6):
            clr,pe=sim(st,cand,-1,1.5,PP,th,vf,0.35)
            sc=10*min(clr,0.6)-0.04*abs(cand-track)-(5 if abs(pe)>55 else 0)
            if best is None or sc>best[0]: best=(sc,cand,clr,pe)
        cs=best[1];cclr=best[2]
        if cclr>=0.6:
            clr,pe=sim(st,track,-1,1.5,PP,th,vf,0.35)
            if clr>=0.6 and abs(pe)<55: cs=track
    if cclr<0.12:
        nf+=1;mode='fwd';trav=0.0;fsteer=0.0;cclr=9.0
        print('TOFWD t=%.1f phi=%.1f mn=%.2f'%(obs['t'],phi,mn))
        if nf==4: wake('fourth pull-forward')
        return (st,0.0,look)
    spd=-0.3 if (cclr<0.4 or abs(phi)>30) else (-0.6 if cclr<0.8 else -1.0)
    if abs(st-cs)>20: spd=max(spd,-0.15)
    if n%15==0:
        print('t=%.1f phi=%.1f phid=%.0f ang=%.0f tr=%.0f cs=%.0f clr=%.2f mn=%.2f np=%d'%(obs['t'],phi,phid,ang,track,cs,cclr,mn,len(PP)))
    return (cs,spd,look)
